class SelectivePolicy:
    """Learned Deferral with Equalized Deferral Rates (LD-EqDR).

    Algorithm:
    1. Train a compact meta-model to predict correctness from enhanced
       confidence features → gives strong AUROC and selective risk.
    2. Compute per-group thresholds so that each group has the same
       deferral rate (= 1 - target_coverage) → minimizes deferral_rate_gap.
    3. Apply a coverage correction offset via binary search on calibration
       data → ensures overall coverage matches target.

    Key insight: using the *learned* score (not raw confidence) for
    groupwise thresholding gives better selective risk than groupwise
    thresholding on max_prob, while equalized per-group thresholds
    ensure deferral fairness. The coverage correction step handles
    any residual mismatch.
    """

    def __init__(self, target_coverage: float = TARGET_COVERAGE_DEFAULT, random_state: int = 0):
        self.target_coverage = float(target_coverage)
        self.random_state = int(random_state)
        self.threshold_: float = 0.5
        self.group_thresholds_: dict[int, float] = {}
        self.meta_model_ = None
        self.strategy_name = "learned_equalized_deferral"
        self._offset: float = 0.0

    def _build_features(self, probs: np.ndarray, groups: np.ndarray, X: np.ndarray | None = None) -> np.ndarray:
        """Build enhanced confidence features."""
        base_feats = _confidence_features(probs, groups, X)
        p1 = probs[:, 1]
        p0 = probs[:, 0]
        logit = np.log(np.clip(p1, 1e-8, 1.0 - 1e-8) / np.clip(p0, 1e-8, 1.0 - 1e-8))
        return np.column_stack([base_feats, logit])

    def fit(self, probs: np.ndarray, y_true: np.ndarray, groups: np.ndarray, X: np.ndarray | None = None) -> "SelectivePolicy":
        features = self._build_features(probs, groups, X)
        correct = (np.argmax(probs, axis=1) == y_true).astype(int)

        # Train meta-classifier
        self.meta_model_ = Pipeline(
            steps=[
                ("scale", StandardScaler()),
                (
                    "clf",
                    LogisticRegression(
                        max_iter=1000,
                        solver="lbfgs",
                        class_weight="balanced",
                        C=1.0,
                        random_state=self.random_state,
                    ),
                ),
            ]
        )
        self.meta_model_.fit(features, correct)
        raw_scores = self.meta_model_.predict_proba(features)[:, 1]

        quantile = float(np.clip(1.0 - self.target_coverage, 0.0, 1.0))

        # Per-group thresholds: each group defers the same fraction
        self.group_thresholds_ = {}
        for gid in np.unique(groups):
            mask = groups == gid
            if mask.sum() < 2:
                self.group_thresholds_[int(gid)] = float(np.quantile(raw_scores, quantile))
            else:
                self.group_thresholds_[int(gid)] = float(np.quantile(raw_scores[mask], quantile))

        self.threshold_ = float(np.quantile(raw_scores, quantile))

        # Coverage correction via binary search on a uniform offset
        def compute_coverage(offset):
            accept = np.array([
                raw_scores[i] >= (self.group_thresholds_.get(int(groups[i]), self.threshold_) - offset)
                for i in range(len(raw_scores))
            ])
            return float(accept.mean())

        lo, hi = -2.0, 2.0
        for _ in range(60):
            mid = (lo + hi) / 2.0
            cov = compute_coverage(mid)
            if cov < self.target_coverage:
                lo = mid
            else:
                hi = mid
        self._offset = (lo + hi) / 2.0

        # Apply offset to all thresholds
        for gid in self.group_thresholds_:
            self.group_thresholds_[gid] -= self._offset
        self.threshold_ -= self._offset

        return self

    def acceptance_score(self, probs: np.ndarray, groups: np.ndarray, X: np.ndarray | None = None) -> np.ndarray:
        """Learned correctness probability — used for AUROC evaluation."""
        if self.meta_model_ is None:
            return np.max(probs, axis=1)
        features = self._build_features(probs, groups, X)
        return self.meta_model_.predict_proba(features)[:, 1]

    def predict_accept(self, probs: np.ndarray, groups: np.ndarray, X: np.ndarray | None = None) -> np.ndarray:
        """Accept/defer using group-specific thresholds."""
        scores = self.acceptance_score(probs, groups, X)
        thresholds = np.array([
            self.group_thresholds_.get(int(g), self.threshold_) for g in groups
        ], dtype=float)
        return scores >= thresholds

    def calibration_summary(self) -> dict[str, float]:
        summary = {
            "threshold": float(self.threshold_),
            "offset": float(self._offset),
        }
        for group_id, threshold in self.group_thresholds_.items():
            summary[f"threshold_group_{group_id}"] = float(threshold)
        return summary
